#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Every catalog SKU must appear, including ones with no movements that day
# (SKU-9 is in the catalog, so it always gets a line).
{
    awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
         END { for (sku in net) print sku, net[sku] }' movements.log
    echo "SKU-9 0"
} | sort > stock.txt
